-- Chike and Zech's Space Adventure, redrawn to match the other books: new pictures from Chike's and Zech's character
-- sheets for every story page, one new page (the imaginary flight), and the payoff (Mom and Dad) as a full page of its
-- own beside its text. The cover and closing cover stay. Run AFTER the pictures in assets/books/space-adventure/ are live.
-- Each statement only touches a page if the page at that position has the expected id; one transaction.
--   before: 1 cover | 2 3 | 4 5 | 6 7(payoff text + small picture) | 8 The End | 9 closing cover
--   after:  1 cover | 2 3 | 4 5 | 6 7 flight | 8 payoff text, 9 payoff picture | 10 The End, 11 closing cover

begin;
update stories set data = coalesce(jsonb_set(data, '{pages,1,layers,0}', (data->'pages'->1->'layers'->0) || '{"src": "/assets/books/space-adventure/saturday-morning.jpg", "alt": "On Saturday morning, Chike kneels by his little brother''s bed holding a box of crayons and whispering an idea while Zech rubs his sleepy eyes"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->1->>'id' = 'pg-mig2-2';
update stories set data = coalesce(jsonb_set(data, '{pages,1,background}', '{"type": "color", "value": "#DFE8F4"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->1->>'id' = 'pg-mig2-2';
update stories set data = coalesce(jsonb_set(data, '{pages,2,layers,1}', (data->'pages'->2->'layers'->1) || '{"src": "/assets/books/space-adventure/rocket-idea.jpg", "alt": "Among cardboard boxes on the bedroom floor, Zech throws his arms up under a glowing thought bubble of a rocket and planets while Chike gives a thumbs-up"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->2->>'id' = 'pg-mig2-3';
update stories set data = coalesce(jsonb_set(data, '{pages,2,background}', '{"type": "color", "value": "#F6E6DC"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->2->>'id' = 'pg-mig2-3';
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers,1}', (data->'pages'->3->'layers'->1) || '{"src": "/assets/books/space-adventure/building-the-foil-rocket.jpg", "alt": "Chike wraps a tall cardboard rocket in shiny foil while Zech paints a big orange planet, with more painted planets drying on the floor"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->3->>'id' = 'pg-mig2-4' and data->'pages'->3->'layers'->1->>'type' = 'image';
update stories set data = coalesce(jsonb_set(data, '{pages,3,background}', '{"type": "color", "value": "#DFE7F4"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->3->>'id' = 'pg-mig2-4';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers,0}', (data->'pages'->4->'layers'->0) || '{"src": "/assets/books/space-adventure/galaxy-bedroom.jpg", "alt": "In their bedroom turned galaxy, Zech hugs the biggest planet, purple and blue with a paper ring, and Chike holds out his orange-and-green planet"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->4->>'id' = 'pg-mig2-5' and data->'pages'->4->'layers'->0->>'type' = 'image';
update stories set data = coalesce(jsonb_set(data, '{pages,4,background}', '{"type": "color", "value": "#DDE2F6"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->4->>'id' = 'pg-mig2-5';
-- the wide pictures alternate top, bottom, top, bottom: page 4's picture goes on top and page 5's to the bottom
-- (after their pictures are set above; on a re-run the type checks skip both)
update stories set data = coalesce(jsonb_set(data, '{pages,3,layers}', jsonb_build_array((data->'pages'->3->'layers'->1) || '{"y": 0, "placement": "top-half"}'::jsonb, (data->'pages'->3->'layers'->0) || '{"y": 55}'::jsonb)), data) where id = 'book-space-adventure' and data->'pages'->3->>'id' = 'pg-mig2-4' and data->'pages'->3->'layers'->0->>'type' = 'text';
update stories set data = coalesce(jsonb_set(data, '{pages,4,layers}', jsonb_build_array((data->'pages'->4->'layers'->1) || '{"y": 10}'::jsonb, (data->'pages'->4->'layers'->0) || '{"y": 50, "placement": "bottom-half"}'::jsonb)), data) where id = 'book-space-adventure' and data->'pages'->4->>'id' = 'pg-mig2-5' and data->'pages'->4->'layers'->0->>'type' = 'image';
update stories set data = coalesce(jsonb_set(data, '{pages,5,layers,0}', (data->'pages'->5->'layers'->0) || '{"src": "/assets/books/space-adventure/cereal-box-blast-off.jpg", "alt": "Wearing cereal-box astronaut helmets, Chike and Zech pretend to blast off beside their foil rocket, Chike pointing up and shouting"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->5->>'id' = 'pg-mig2-6';
update stories set data = coalesce(jsonb_set(data, '{pages,5,background}', '{"type": "color", "value": "#F7E5DC"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->5->>'id' = 'pg-mig2-6';
-- the payoff text page: text only now, its picture gets a full page of its own
update stories set data = coalesce(jsonb_set(data, '{pages,6,layers}', jsonb_build_array((data->'pages'->6->'layers'->0) || '{"y": 30, "h": 40}'::jsonb)), data) where id = 'book-space-adventure' and data->'pages'->6->>'id' = 'pg-mig2-7' and jsonb_array_length(data->'pages'->6->'layers') = 2;
update stories set data = coalesce(jsonb_set(data, '{pages,6,background}', '{"type": "color", "value": "#DDE4F5"}'::jsonb), data) where id = 'book-space-adventure' and data->'pages'->6->>'id' = 'pg-mig2-7';
-- the payoff picture right after its text (inserted before the flight page, so its position is still 6)
update stories set data = coalesce(jsonb_insert(data, '{pages,6}', '{"id": "pg-space-payoff", "layers": [{"h": 100, "w": 100, "x": 0, "y": 0, "id": "ly-space-payoff", "alt": "In their galaxy bedroom, Mom gives Chike and Zech a big double high five while Dad stands behind them with a proud smile", "fit": "cover", "src": "/assets/books/space-adventure/mom-and-dad-high-five-payoff.jpg", "type": "image", "locked": false, "placement": "full-bg"}], "background": {"type": "color", "value": "#DDE4F5"}}'::jsonb, true), data) where id = 'book-space-adventure' and data->'pages'->6->>'id' = 'pg-mig2-7' and data::text not like '%pg-space-payoff%';
-- the new flight page after the blast-off page
update stories set data = coalesce(jsonb_insert(data, '{pages,5}', '{"id": "pg-space-flight", "layers": [{"h": 35, "w": 80, "x": 10, "y": 10, "id": "ly-space-flight-text", "type": "text", "align": "left", "color": "", "style": "body", "locked": false, "content": "Zoom! In their imaginations, the rocket flew past Zectune’s swirly rings and all the way around Chikopia. Chike and Zech waved at the stars as they zipped through space."}, {"h": 50, "w": 100, "x": 0, "y": 50, "id": "ly-space-flight", "alt": "In their imagination, Chike and Zech fly their foil rocket through space past a ringed purple planet and an orange-and-green planet, waving at the stars", "fit": "cover", "src": "/assets/books/space-adventure/flying-past-the-planets.jpg", "type": "image", "locked": false, "placement": "bottom-half"}], "background": {"type": "color", "value": "#F4DEE9"}}'::jsonb, true), data) where id = 'book-space-adventure' and data->'pages'->5->>'id' = 'pg-mig2-6' and data::text not like '%pg-space-flight%';
-- the Read page card: the payoff, cropped wide
update stories set data = data || '{"card": {"src": "/assets/books/space-adventure/card.jpg", "alt": "Mom gives Chike and Zech a big high five in their galaxy bedroom while Dad smiles proudly"}}'::jsonb where id = 'book-space-adventure';
commit;
